1	package org.jsoup.safety;
2	
3	import org.jsoup.Jsoup;
4	import org.jsoup.nodes.Document;
5	import org.jsoup.nodes.Element;
6	import org.junit.jupiter.api.Test;
7	
8	import static org.junit.jupiter.api.Assertions.*;
9	
10	/**
11	 Tests for per-candidate cleaning of {@code srcset} attributes in the {@link Cleaner}.
12	 */
13	public class SrcsetCleanerTest {
14	
15	    private static Safelist safelist() {
16	        return Safelist.relaxed().addAttributes("img", "srcset");
17	    }
18	
19	    @Test void srcsetRemovedWhenNotAllowed() {
20	        // without the attribute in the safelist, the existing attribute-removal behavior is unchanged
21	        String html = "<img src=\"http://example.com/src.jpg\" srcset=\"http://example.com/a.jpg 1x\">";
22	        String clean = Jsoup.clean(html, Safelist.relaxed());
23	        assertEquals("<img src=\"http://example.com/src.jpg\">", clean);
24	    }
25	
26	    @Test void retainsCandidatesAndDescriptors() {
27	        String html = "<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x, http://example.com/c.jpg 300w\">";
28	        String clean = Jsoup.clean(html, safelist());
29	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x, http://example.com/c.jpg 300w\">", clean);
30	    }
31	
32	    @Test void retainsCandidateWithoutDescriptor() {
33	        String clean = Jsoup.clean("<img srcset=\"http://example.com/a.jpg, http://example.com/b.jpg 2x\">", safelist());
34	        assertEquals("<img srcset=\"http://example.com/a.jpg, http://example.com/b.jpg 2x\">", clean);
35	    }
36	
37	    @Test void normalizesWhitespaceAroundDescriptors() {
38	        String clean = Jsoup.clean("<img srcset=\"  http://example.com/a.jpg     1x  , http://example.com/b.jpg  2x \">", safelist());
39	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
40	    }
41	
42	    @Test void resolvesRelativeCandidatesAgainstBaseUri() {
43	        String html = "<img srcset=\"/a.jpg 1x, /b.jpg 2x\">";
44	        String clean = Jsoup.clean(html, "http://example.com/path/", safelist());
45	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
46	    }
47	
48	    @Test void preservesRelativeCandidatesWhenConfigured() {
49	        Safelist safelist = safelist().preserveRelativeLinks(true);
50	        String clean = Jsoup.clean("<img srcset=\"/a.jpg 1x, http://example.com/b.jpg 2x\">", "http://example.com/", safelist);
51	        assertEquals("<img srcset=\"/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
52	    }
53	
54	    @Test void dropsUnresolvableRelativeCandidatesWithoutBase() {
55	        String clean = Jsoup.clean("<img srcset=\"/a.jpg 1x\">", safelist());
56	        assertEquals("<img>", clean);
57	    }
58	
59	    @Test void dropsJavascriptCandidateAndKeepsRest() {
60	        String html = "<img srcset=\"javascript:alert(1) 1x, http://example.com/a.jpg 1x\">";
61	        String clean = Jsoup.clean(html, safelist());
62	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", clean);
63	    }
64	
65	    @Test void dropsDisguisedJavascriptCandidate() {
66	        // entity-decoded tabs/newlines/control characters must not smuggle a scheme through
67	        String html = "<img srcset=\"&#0013;ja&Tab;va&Tab;script&#0010;:alert(1) 1x, http://example.com/a.jpg 1x\">";
68	        String clean = Jsoup.clean(html, "https://", safelist());
69	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", clean);
70	
71	        String colon = "<img srcset=\"ja&Tab;va&Tab;script&colon;alert(1), http://example.com/a.jpg 1x\">";
72	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", Jsoup.clean(colon, "https://", safelist()));
73	    }
74	
75	    @Test void schemeCheckIsCaseInsensitive() {
76	        String clean = Jsoup.clean("<img srcset=\"HTTP://example.com/a.jpg 1x\">", safelist());
77	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", clean);
78	    }
79	
80	    @Test void candidateWithBadDescriptorIsDroppedAlone() {
81	        String html = "<img srcset=\"http://example.com/a.jpg 100zz, "
82	            + "http://example.com/b.jpg 1x 2x, "
83	            + "http://example.com/c.jpg 0w, "
84	            + "http://example.com/d.jpg -5w, "
85	            + "http://example.com/e.jpg 1.5w, "
86	            + "http://example.com/f.jpg 100W, "
87	            + "http://example.com/g.jpg, "
88	            + "http://example.com/h.jpg (orientation: portrait), "
89	            + "http://example.com/i.jpg 2x\">";
90	        String clean = Jsoup.clean(html, safelist());
91	        assertEquals("<img srcset=\"http://example.com/g.jpg, http://example.com/i.jpg 2x\">", clean);
92	    }
93	
94	    @Test void illegalDensityValuesAreDropped() {
95	        String html = "<img srcset=\"http://example.com/a.jpg -1x, http://example.com/b.jpg x, "
96	            + "http://example.com/c.jpg .x, http://example.com/d.jpg 1ex, http://example.com/e.jpg 2x\">";
97	        String clean = Jsoup.clean(html, safelist());
98	        assertEquals("<img srcset=\"http://example.com/e.jpg 2x\">", clean);
99	    }
100	
101	    @Test void validDensityGrammarAccepted() {
102	        String html = "<img srcset=\"http://example.com/a.jpg 0.5x, http://example.com/b.jpg +1x, "
103	            + "http://example.com/c.jpg 1e2x, http://example.com/d.jpg .25x\">";
104	        String clean = Jsoup.clean(html, safelist());
105	        assertEquals("<img srcset=\"http://example.com/a.jpg 0.5x, http://example.com/b.jpg +1x, "
106	            + "http://example.com/c.jpg 1e2x, http://example.com/d.jpg .25x\">", clean);
107	    }
108	
109	    @Test void emptyAndConsecutiveAndTrailingSeparatorsDoNotThrowOrSwallow() {
110	        String html = "<img srcset=\",, http://example.com/a.jpg 1x,,, http://example.com/b.jpg 2x,\">";
111	        String clean = Jsoup.clean(html, safelist());
112	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
113	    }
114	
115	    @Test void emptyValueRemovesAttribute() {
116	        assertEquals("<img>", Jsoup.clean("<img srcset=\"\">", safelist()));
117	        assertEquals("<img>", Jsoup.clean("<img srcset=\"   \">", safelist()));
118	        assertEquals("<img>", Jsoup.clean("<img srcset=\",,\">", safelist()));
119	    }
120	
121	    @Test void quotedUrlTreatsCommaAndWhitespaceAsLiteral() {
122	        // double-quoted address: the embedded comma and space belong to the address, quotes are not part of it
123	        String html = "<img srcset='\"http://example.com/a,b.jpg\" 1x, http://example.com/c.jpg 2x'>";
124	        String clean = Jsoup.clean(html, safelist());
125	        assertEquals("<img srcset=\"&quot;http://example.com/a,b.jpg&quot; 1x, http://example.com/c.jpg 2x\">", clean);
126	
127	        // single quotes delimit the address the same way
128	        String single = "<img srcset=\"'http://example.com/a b.jpg' 1x, http://example.com/c.jpg 2x\">";
129	        String cleanSingle = Jsoup.clean(single, safelist());
130	        assertEquals("<img srcset=\"'http://example.com/a b.jpg' 1x, http://example.com/c.jpg 2x\">", cleanSingle);
131	
132	        // quoted address with no descriptor still protects the inner comma
133	        String noDesc = "<img srcset='\"http://example.com/a,b.jpg\", http://example.com/c.jpg 2x'>";
134	        assertEquals("<img srcset=\"&quot;http://example.com/a,b.jpg&quot;, http://example.com/c.jpg 2x\">",
135	            Jsoup.clean(noDesc, safelist()));
136	    }
137	
138	    @Test void quotedUrlIsRecheckedAfterReparse() {
139	        // serialized quotes must parse back to the same single address and remain protocol-checked
140	        String html = "<img srcset='\"javascript:alert(1)\", http://example.com/c.jpg 2x'>";
141	        String clean = Jsoup.clean(html, safelist());
142	        assertEquals("<img srcset=\"http://example.com/c.jpg 2x\">", clean);
143	        assertEquals(clean, Jsoup.clean(clean, safelist()));
144	    }
145	
146	    @Test void malformedQuotedUrlIsDroppedAlone() {
147	        // a descriptor glued directly to the closing quote invalidates only that candidate
148	        String glued = "<img srcset='\"http://example.com/a.jpg\"1x, http://example.com/c.jpg 2x'>";
149	        assertEquals("<img srcset=\"http://example.com/c.jpg 2x\">", Jsoup.clean(glued, safelist()));
150	
151	        // an unterminated quote does not swallow a later valid candidate
152	        String unterminated = "<img srcset='\"http://example.com/a.jpg 1x, http://example.com/c.jpg 2x'>";
153	        assertEquals("<img srcset=\"http://example.com/c.jpg 2x\">", Jsoup.clean(unterminated, safelist()));
154	
155	        // an empty quoted address is no candidate at all
156	        String empty = "<img srcset='\"\" 1x, http://example.com/c.jpg 2x'>";
157	        assertEquals("<img srcset=\"http://example.com/c.jpg 2x\">", Jsoup.clean(empty, safelist()));
158	    }
159	
160	    @Test void zeroAndNonFiniteDensitiesAreDropped() {
161	        String html = "<img srcset=\"http://example.com/a.jpg 0x, http://example.com/b.jpg +0x, "
162	            + "http://example.com/c.jpg 0.0x, http://example.com/d.jpg 1e999x, http://example.com/e.jpg 2x\">";
163	        String clean = Jsoup.clean(html, safelist());
164	        assertEquals("<img srcset=\"http://example.com/e.jpg 2x\">", clean);
165	    }
166	
167	    @Test void controlCharCandidatesAreRejectedNotStripped() {
168	        // an entity-decoded control character in the address must drop the candidate rather than smuggle a scheme
169	        String html = "<img srcset=\"java&#x09;script:alert(1), http://example.com/ok.jpg 1x\">";
170	        String clean = Jsoup.clean(html, "https://", safelist());
171	        assertEquals("<img srcset=\"http://example.com/ok.jpg 1x\">", clean);
172	
173	        // a raw control char inside an otherwise-good URL invalidates that candidate only
174	        String raw = "<img srcset=\"http://example.com/a&#x0a;.jpg 1x, http://example.com/ok.jpg 2x\">";
175	        assertEquals("<img srcset=\"http://example.com/ok.jpg 2x\">", Jsoup.clean(raw, "https://", safelist()));
176	    }
177	
178	    @Test void quotedCandidateOutputIsIdempotent() {
179	        String html = "<img srcset='\"http://example.com/a,b.jpg\" 1x, \"http://example.com/c d.jpg\" 2x'>";
180	        Cleaner cleaner = new Cleaner(safelist());
181	        Document once = cleaner.clean(Jsoup.parseBodyFragment(html, "http://example.com/"));
182	        Document twice = cleaner.clean(once);
183	        assertEquals(once.body().html(), twice.body().html());
184	        // both addresses survive, each still carrying its single descriptor (no ghost candidates from inner punctuation)
185	        String srcset = once.expectFirst("img").attr("srcset");
186	        assertTrue(srcset.contains("a,b.jpg"));
187	        assertTrue(srcset.contains("c d.jpg"));
188	        assertTrue(srcset.contains(" 1x"));
189	        assertTrue(srcset.contains(" 2x"));
190	        assertEquals(2, srcset.split("\\s[12]x", -1).length - 1);
191	    }
192	
193	    @Test void commaInsideDataUrlIsNotASeparator() {
194	        Safelist safelist = safelist().addProtocols("img", "srcset", "http", "https", "data");
195	        // data: URLs with no descriptor: the comma that is part of the data must survive the boundary comma
196	        String html = "<img srcset=\"data:text/plain,Hello 1x, http://example.com/a.jpg 2x\">";
197	        String clean = Jsoup.clean(html, safelist);
198	        assertEquals("<img srcset=\"data:text/plain,Hello 1x, http://example.com/a.jpg 2x\">", clean);
199	
200	        String noDescriptor = "<img srcset=\"data:,foo, http://example.com/a.jpg 2x\">";
201	        String clean2 = Jsoup.clean(noDescriptor, safelist);
202	        assertEquals("<img srcset=\"data:,foo, http://example.com/a.jpg 2x\">", clean2);
203	    }
204	
205	    @Test void dataUrlDroppedUnlessProtocolAllowed() {
206	        String html = "<img srcset=\"data:image/gif;base64,R0lGOD 1x, http://example.com/a.jpg 1x\">";
207	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", Jsoup.clean(html, safelist()));
208	
209	        Safelist withData = safelist().addProtocols("img", "srcset", "http", "https", "data");
210	        String clean = Jsoup.clean(html, withData);
211	        assertEquals("<img srcset=\"data:image/gif;base64,R0lGOD 1x, http://example.com/a.jpg 1x\">", clean);
212	    }
213	
214	    @Test void explicitSrcsetProtocolsAreIndependentOfSrc() {
215	        Safelist safelist = Safelist.relaxed()
216	            .addAttributes("img", "srcset")
217	            .addProtocols("img", "srcset", "data");
218	        String html = "<img src=\"http://example.com/src.jpg\" srcset=\"data:text/plain,Hi 1x, http://example.com/a.jpg 1x\">";
219	        String clean = Jsoup.clean(html, safelist);
220	        // srcset only allows data:; src still uses its own http/https policy
221	        assertEquals("<img src=\"http://example.com/src.jpg\" srcset=\"data:text/plain,Hi 1x\">", clean);
222	    }
223	
224	    @Test void fallsBackToSrcProtocolsThenAllTag() {
225	        Safelist safelist = new Safelist()
226	            .addTags("img")
227	            .addAttributes(":all", "srcset")
228	            .addProtocols(":all", "src", "http", "https");
229	        String clean = Jsoup.clean("<img srcset=\"http://example.com/a.jpg 1x, javascript:alert(1)\">", "http://example.com/", safelist);
230	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", clean);
231	    }
232	
233	    @Test void noProtocolPolicyAcceptsLikeOrdinaryUntypedAttribute() {
234	        Safelist safelist = new Safelist().addTags("img").addAttributes("img", "srcset");
235	        String clean = Jsoup.clean("<img srcset=\"javascript:alert(1) 1x, /a.jpg\">", safelist);
236	        assertEquals("<img srcset=\"javascript:alert(1) 1x, /a.jpg\">", clean);
237	    }
238	
239	    @Test void worksOnAnyTag() {
240	        Safelist safelist = new Safelist()
241	            .addTags("source")
242	            .addAttributes("source", "srcset")
243	            .addProtocols("source", "src", "http", "https");
244	        String clean = Jsoup.clean("<source srcset=\"http://example.com/a.jpg 1x, javascript:x 2x\">", "http://example.com/", safelist);
245	        assertEquals("<source srcset=\"http://example.com/a.jpg 1x\">", clean);
246	    }
247	
248	    @Test void srcAndHrefAndOtherAttributesAreUnaffected() {
249	        String html = "<img src=\"/src.jpg\" alt=\"Hi\" title=\"T\" srcset=\"javascript:bad 1x, http://example.com/a.jpg 1x\">"
250	            + "<a href=\"/x\">x</a>";
251	        String clean = Jsoup.clean(html, "http://example.com/", safelist());
252	        assertEquals("<img src=\"http://example.com/src.jpg\" alt=\"Hi\" title=\"T\" srcset=\"http://example.com/a.jpg 1x\">"
253	            + "<a href=\"http://example.com/x\">x</a>", clean);
254	    }
255	
256	    @Test void nodesAndDocumentOrderArePreserved() {
257	        String html = "<p>Before</p>"
258	            + "<img srcset=\"http://example.com/a.jpg 1x, javascript:bad 2x\">"
259	            + "<img srcset=\"http://example.com/b.jpg 1x\">"
260	            + "<p>After</p>";
261	        String clean = org.jsoup.TextUtil.stripNewlines(Jsoup.clean(html, "http://example.com/", safelist()));
262	        assertEquals("<p>Before</p>"
263	            + "<img srcset=\"http://example.com/a.jpg 1x\">"
264	            + "<img srcset=\"http://example.com/b.jpg 1x\">"
265	            + "<p>After</p>", clean);
266	    }
267	
268	    @Test void oneBadSrcsetDoesNotAffectOtherElements() {
269	        Document dirty = Jsoup.parseBodyFragment(
270	            "<img srcset=\"javascript:bad 1x\"><img srcset=\"http://example.com/ok.jpg 1x\">",
271	            "http://example.com/");
272	        Document clean = new Cleaner(safelist()).clean(dirty);
273	        assertEquals("<img><img srcset=\"http://example.com/ok.jpg 1x\">", clean.body().html());
274	    }
275	
276	    @Test void inputDocumentIsNotModified() {
277	        Document dirty = Jsoup.parseBodyFragment(
278	            "<img srcset=\"/a.jpg 1x, javascript:bad 2x\">", "http://example.com/");
279	        Element img = dirty.expectFirst("img");
280	        String original = img.attr("srcset");
281	        new Cleaner(safelist()).clean(dirty);
282	        assertEquals(original, img.attr("srcset"));
283	        assertEquals("/a.jpg 1x, javascript:bad 2x", img.attr("srcset"));
284	    }
285	
286	    @Test void cleaningIsIdempotentAndReparseable() {
287	        String html = "<img srcset=\"  /a.jpg     1x ,  http://example.com/b.jpg  2x , javascript:bad 3x\">";
288	        Cleaner cleaner = new Cleaner(safelist());
289	        Document once = cleaner.clean(Jsoup.parseBodyFragment(html, "http://example.com/"));
290	        Document twice = cleaner.clean(once);
291	
292	        String expected = "<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">";
293	        assertEquals(expected, once.body().html());
294	        assertEquals(expected, twice.body().html());
295	
296	        // the result must parse again into the same candidates and descriptors
297	        Document reparsed = Jsoup.parse(once.body().html());
298	        assertEquals(once.body().html(), cleaner.clean(reparsed).body().html());
299	        Element img = reparsed.expectFirst("img");
300	        assertEquals(2, img.attr("srcset").split(",").length);
301	        assertTrue(img.attr("srcset").contains("1x"));
302	        assertTrue(img.attr("srcset").contains("2x"));
303	    }
304	
305	    @Test void repeatedCleaningOfSameInputIsStable() {
306	        Document dirty = Jsoup.parseBodyFragment(
307	            "<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">", "http://example.com/");
308	        Cleaner cleaner = new Cleaner(safelist());
309	        assertEquals(cleaner.clean(dirty).body().html(), cleaner.clean(dirty).body().html());
310	    }
311	
312	    @Test void isValidReflectsDroppedCandidates() {
313	        Cleaner cleaner = new Cleaner(safelist());
314	        Document ok = Jsoup.parseBodyFragment("<img srcset=\"http://example.com/a.jpg 1x\">", "http://example.com/");
315	        Document bad = Jsoup.parseBodyFragment("<img srcset=\"http://example.com/a.jpg 1x, javascript:alert(1)\">", "http://example.com/");
316	        Document badDescriptor = Jsoup.parseBodyFragment("<img srcset=\"http://example.com/a.jpg nope\">", "http://example.com/");
317	        assertTrue(cleaner.isValid(ok));
318	        assertFalse(cleaner.isValid(bad));
319	        assertFalse(cleaner.isValid(badDescriptor));
320	    }
321	
322	    @Test void entitiesInUrlsAreHandledAndReserialized() {
323	        String html = "<img srcset=\"http://example.com/a?b=1&amp;c=2 1x\">";
324	        String clean = Jsoup.clean(html, safelist());
325	        assertEquals("<img srcset=\"http://example.com/a?b=1&amp;c=2 1x\">", clean);
326	    }
327	
328	    @Test void commaInsideParenthesizedDescriptorDoesNotSwallowNextCandidate() {
329	        // the comma inside the (invalid, image-relevant) descriptor is not a candidate boundary; it is dropped alone
330	        String html = "<img srcset=\"http://example.com/a.jpg (min-width: 400px, foo: bar), http://example.com/b.jpg 1x\">";
331	        String clean = Jsoup.clean(html, safelist());
332	        assertEquals("<img srcset=\"http://example.com/b.jpg 1x\">", clean);
333	    }
334	
335	    @Test void tabInsideSchemeIsStrippedBeforeProtocolCheck() {
336	        String html = "<img srcset=\"http://example.com/ok.jpg 1x, ja&Tab;vas&#x09;cript:alert(1) 2x\">";
337	        String clean = Jsoup.clean(html, "https://", safelist());
338	        assertEquals("<img srcset=\"http://example.com/ok.jpg 1x\">", clean);
339	    }
340	
341	    @Test void leadingControlCharsDoNotBypassSchemeCheck() {
342	        String html = "<img srcset=\"&#01;&#10;javascript:alert(1), http://example.com/ok.jpg 1x\">";
343	        String clean = Jsoup.clean(html, "https://", safelist());
344	        assertEquals("<img srcset=\"http://example.com/ok.jpg 1x\">", clean);
345	    }
346	
347	    @Test void badCandidateBeforeAndAfterGoodOneDoesNotCorruptOutput() {
348	        String html = "<img srcset=\"bad 0w, http://example.com/a.jpg 1x, javascript:x, http://example.com/b.jpg 2x, nope 1x 2x\">";
349	        String clean = Jsoup.clean(html, "http://example.com/", safelist());
350	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
351	
352	        // re-clean of the clean result is stable
353	        assertEquals(clean, Jsoup.clean(clean, "http://example.com/", safelist()));
354	    }
355	
356	    @Test void descriptorSemanticsSurviveReparse() {
357	        Document doc = Jsoup.parse(Jsoup.clean(
358	            "<img srcset=\"http://example.com/a.jpg, http://example.com/b.jpg 2x, http://example.com/c.jpg 480w\">",
359	            safelist()));
360	        Element img = doc.expectFirst("img");
361	        String srcset = img.attr("srcset");
362	        assertTrue(srcset.contains("http://example.com/a.jpg,"));
363	        assertTrue(srcset.contains("2x"));
364	        assertTrue(srcset.contains("480w"));
365	    }
366	
367	    @Test void neverThrowsOnHostileInput() {
368	        String[] hostile = {
369	            "", " ", ",", ",,,", " , , ",
370	            "http://example.com/a.jpg,",
371	            "http://example.com/a.jpg , , ,",
372	            "http://example.com/a.jpg (",
373	            "http://example.com/a.jpg ((,,,)) 1x, http://example.com/b.jpg 1x",
374	            "http://example.com/a.jpg \t\n\r\f 1x  ,  http://example.com/b.jpg",
375	            "http://example.com/a.jpg 99999999999999999999999999999999w, http://example.com/b.jpg 1x"
376	        };
377	        Cleaner cleaner = new Cleaner(safelist());
378	        for (String value : hostile) {
379	            Document doc = Jsoup.parseBodyFragment("<img srcset=\"" + value + "\">", "http://example.com/");
380	            Document clean = assertDoesNotThrow(() -> cleaner.clean(doc));
381	            // a surviving srcset must never contain a javascript candidate
382	            clean.select("img").forEach(img ->
383	                assertFalse(img.attr("srcset").toLowerCase().contains("javascript")));
384	        }
385	    }
386	}
