import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;

public class Probe {
    static Safelist sl() { return Safelist.relaxed().addAttributes("img", "srcset"); }
    static void t(String base, String srcset) {
        String html = "<img srcset=\"" + srcset + "\">";
        String clean = base == null ? Jsoup.clean(html, sl()) : Jsoup.clean(html, base, sl());
        // idempotence
        String again = Jsoup.clean(clean, base == null ? "" : base, sl());
