#!/usr/bin/env bash
set -eu
mode="${1:---all}"
case "$mode" in
  --all|--case-candidates|--case-stability) ;;
  *) echo "environment/adapter failure: unsupported mode $mode" >&2; exit 2 ;;
esac
root="$(pwd)"
mvn -q -DskipTests compile
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
cat > "$work/Check.java" <<'JAVA'
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class Check {
    // Coverage: quoted/encoded candidate boundaries -> candidates(); descriptor and protocol rejection -> candidates();
    // malformed candidate isolation -> candidates(); source immutability, repeat cleaning, and opt-in/legacy behavior -> stability().
    // Counterexamples: splitting every comma, accepting zero density, stripping controls, swallowing a later candidate,
    // mutating the source, or retaining srcset without opt-in each makes a corresponding assertion fail.
    static void ok(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
    static Cleaner cleaner(boolean enabled) {
        Safelist list = Safelist.relaxed();
        if (enabled) list.addAttributes("img", "srcset");
        return new Cleaner(list);
    }
    static Document clean(String html) {
        return cleaner(true).clean(Jsoup.parseBodyFragment(html, "https://base.test/"));
    }
    static Element firstImg(Document d) {
        Element e = d.selectFirst("img");
        ok(e != null, "missing img");
        return e;
    }
    static void candidates() {
        Document quoted = clean("<img srcset='\"https://example.test/a,b.jpg\" 1x, https://example.test/e.jpg +2x, https://example.test/zero.jpg 0x, https://example.test/neg.jpg -1x, https://example.test/js.jpg 1e999x'>");
        String q = firstImg(quoted).attr("srcset");
        ok(q.contains("\"https://example.test/a,b.jpg\" 1x"), "quoted comma/descriptor was not preserved: " + q);
        ok(q.contains("https://example.test/e.jpg +2x"), "positive signed density missing: " + q);
        ok(!q.contains("zero.jpg") && !q.contains("neg.jpg") && !q.contains("js.jpg"), "invalid descriptors survived: " + q);

        Document single = clean("<img srcset=\"'https://example.test/c d.jpg' 2x, https://example.test/ok.jpg 3x\">");
        String s = firstImg(single).attr("srcset");
        ok(s.contains("'https://example.test/c d.jpg' 2x"), "single-quoted whitespace address lost: " + s);
        ok(s.contains("https://example.test/ok.jpg 3x"), "later candidate lost after quoted address: " + s);

        Document entity = clean("<img srcset='\"https://example.test/a&#44;b.jpg\" 1x, https://example.test/next.jpg 2x'>");
        String ev = firstImg(entity).attr("srcset");
        ok(ev.contains("a,b.jpg") && ev.contains("next.jpg 2x"), "entity or comma boundary mishandled: " + ev);

        Document malformed = clean("<img srcset='\"https://example.test/bad.jpg 1x, https://example.test/good.jpg 2x'>");
        String m = firstImg(malformed).attr("srcset");
        ok(m.contains("https://example.test/good.jpg 2x"), "later candidate swallowed by unterminated quote: " + m);
        ok(!m.contains("bad.jpg"), "malformed quoted candidate survived: " + m);

        Document unsafe = clean("<img srcset=\"java&#x09;script:alert(1) 1x, data:text/html,x 2x, https://example.test/safe.jpg 4x\">");
        String u = firstImg(unsafe).attr("srcset");
        ok(u.contains("safe.jpg 4x") && !u.contains("javascript") && !u.contains("data:text"), "unsafe protocol/control candidate survived: " + u);

        Document allBad = clean("<img srcset=\"javascript:alert(1) 1x, https://example.test/x.jpg 0x, https://example.test/y.jpg -2x\">");
        ok(!firstImg(allBad).hasAttr("srcset"), "all-invalid srcset was retained");
    }
    static void stability() {
        String html = "<img src=\"https://example.test/src.jpg\" srcset='\"https://example.test/a,b.jpg\" 1x, https://example.test/b.jpg 2x'><p>tail</p>";
        Document source = Jsoup.parseBodyFragment(html, "https://base.test/");
        String before = source.body().html();
        Cleaner c = cleaner(true);
        Document once = c.clean(source);
        ok(source.body().html().equals(before), "clean mutated input document");
        Document twice = c.clean(once);
        ok(once.body().html().equals(twice.body().html()), "cleaning is not idempotent");
        ok(firstImg(once).attr("src").equals("https://example.test/src.jpg"), "ordinary src changed");
        ok(once.selectFirst("p") != null && once.selectFirst("p").text().equals("tail"), "other node changed");

        Document legacy = cleaner(false).clean(Jsoup.parseBodyFragment("<img src=\"https://example.test/src.jpg\" srcset=\"https://example.test/x.jpg 1x\">", "https://base.test/"));
        Element li = firstImg(legacy);
        ok(!li.hasAttr("srcset"), "srcset retained without safelist opt-in");
        ok(li.attr("src").equals("https://example.test/src.jpg"), "legacy src behavior changed");
    }
    public static void main(String[] args) {
        String mode = args.length == 0 ? "--all" : args[0];
        if (mode.equals("--all") || mode.equals("--case-candidates")) candidates();
        if (mode.equals("--all") || mode.equals("--case-stability")) stability();
        System.out.println("srcset acceptance cases passed: " + mode);
    }
}
JAVA
javac -cp "$root/target/classes" -d "$work" "$work/Check.java"
java -cp "$root/target/classes:$work" Check "$mode"

