import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Probe2 {
    static Safelist sl() { return Safelist.relaxed().addAttributes("img", "srcset"); }
    static String clean(String html, String base) {
        return base == null ? Jsoup.clean(html, sl()) : Jsoup.clean(html, base, sl());
    }
    public static void main(String[] a) {
        String base = "http://example.com/";
        String[] desc = {
            "1w","01w","000w","0w","00w","+1w","-1w","1.0w",".5w","1e2w"," 1w","1w ",
            "1W","ｱw","1ｗ","99999999999999999999999999w","2147483648w","9223372036854775807w",
            "9223372036854775808w","100w 200w","100w 100w","100w 1x","1x 100w","100w nope",
            "w","1ww","w1","1w,","1w\t2w","1\nw","+0w","+00w","0x1w","1_00w","٣w"
        };
        int fails = 0;
        for (String d : desc) {
            String html = "<img srcset=\"http://e.com/a.jpg " + d + ", http://e.com/b.jpg 2x\">";
            String c1 = clean(html, base);
            String c2 = clean(c1, base);
            // also reparse serialized html then clean
            String c3 = clean(Jsoup.parse(c1).body().html(), base);
            boolean stable = c1.equals(c2) && c1.equals(c3);
            String mark = stable ? "" : "  <<< UNSTABLE";
            if (!stable) fails++;
            System.out.println("[" + d.replace("\n","\\n").replace("\t","\\t") + "] -> "
                + c1.replaceAll("(^<img|>$)","") + mark);
        }
        System.out.println("unstable: " + fails);
    }
}
