import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Probe3 {
    static Safelist sl() { return Safelist.relaxed().addAttributes("img", "srcset"); }
    static void t(String raw) {
        String html = "<img srcset=" + raw + ">";
        String c1 = Jsoup.clean(html, "http://example.com/", sl());
        String c2 = Jsoup.clean(c1, "http://example.com/", sl());
        String c3 = Jsoup.clean(Jsoup.parse(c1).body().html(), "http://example.com/", sl());
        String flag = (c1.equals(c2) && c1.equals(c3)) ? "" : " <<< UNSTABLE";
        System.out.println(raw);
        System.out.println("  -> " + c1 + flag);
    }
    public static void main(String[] a) {
        // quote nested inside unquoted URL
        t("\"http://e.com/a'b.jpg 1x, http://e.com/c.jpg 2x\"");
        // quote char in the middle of an unquoted run
        t("\"http://e.com/a\"b.jpg 1x, http://e.com/c.jpg 2x\"");
        // quoted URL containing entity for quote
        t("'\"http://e.com/a&quot;b.jpg\" 1x, http://e.com/c.jpg 2x'");
        // empty items around quoted
        t("', \"http://e.com/a.jpg\" 1x, , \"http://e.com/b.jpg\" 2x,'");
        // quoted with tabs/newlines as descriptor separator
        t("'\"http://e.com/a.jpg\"\t1x,\n\"http://e.com/b.jpg\" 2x'");
        // quote glued comma variations
        t("'\"http://e.com/a.jpg\" , http://e.com/c.jpg 2x'");
        // descriptor with leading whitespace token junk: w after space
        t("\"http://e.com/a.jpg  001w, http://e.com/c.jpg 2x\"");
        // unquoted url containing a trailing comma-run then more chars
        t("\"http://e.com/a.jpg,, http://e.com/c.jpg 2x\"");
        // comma immediately followed by quote
        t("\"http://e.com/a.jpg,\\\"http://e.com/b.jpg\\\" 2x\"".replace("\\\"","'"));
        // two quoted candidates, second unsafe
        t("'\"http://e.com/a.jpg\" 1x, \"javascript:x\" 2x, http://e.com/c.jpg 3x'");
        // url containing DEL char
        t("\"http://e.com/a&#x7f;.jpg 1x, http://e.com/ok.jpg 2x\"");
    }
}
