1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.Normalizer;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Attribute;
6	import org.jsoup.nodes.Element;
7	
8	import java.util.ArrayList;
9	import java.util.Collections;
10	import java.util.List;
11	import java.util.Set;
12	
13	/**
14	 Validates and rewrites {@code srcset} attributes, one image candidate at a time.
15	 <p>
16	 The attribute value is split into candidates following the HTML {@code srcset} parsing rules: a candidate consists of a
17	 URL followed by an optional width ({@code w}) or pixel density ({@code x}) descriptor. Commas only separate
18	 candidates at a candidate boundary, so commas nested inside a {@code data:} URL, a quoted value, or entity-decoded
19	 content are preserved. Each surviving URL is checked against the safelist with the same protocol and encoding rules
20	 used for ordinary URI attributes such as {@code src}; invalid descriptors cause their single candidate to be dropped,
21	 without affecting the other candidates.
22	 </p>
23	 */
24	final class SrcsetCleaner {
25	    private SrcsetCleaner() {}
26	
27	    private static final int InDescriptor = 1;
28	    private static final int InParens = 2;
29	    private static final int AfterDescriptor = 3;
30	
31	    /**
32	     Determine whether the supplied attribute is a {@code srcset} attribute that should be handled candidate by
33	     candidate, rather than treated as an ordinary opaque attribute.
34	     @param attr the attribute to test
35	     @return true if it is a {@code srcset} attribute
36	     */
37	    static boolean isSrcset(Attribute attr) {
38	        return "srcset".equalsIgnoreCase(attr.getKey());
39	    }
40	
41	    /**
42	     Clean a {@code srcset} attribute value into a value containing only the acceptable candidates, in their original
43	     order. The input element is not modified; callers must apply the result themselves.
44	     @param el the element carrying the attribute (used for URL resolution against its base URI)
45	     @param rawValue the original attribute value
46	     @param safelist the safelist to validate each candidate URL against
47	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no candidate survived, in
48	     which case the attribute must be removed rather than left empty
49	     */
50	    static Result clean(Element el, String rawValue, Safelist safelist) {
51	        List<Candidate> accepted = new ArrayList<>();
52	        int dropped = 0;
53	        if (rawValue != null && !rawValue.isEmpty()) {
54	            int pos = 0;
55	            int len = rawValue.length();
56	
57	            while (pos < len) {
58	                // 1. Splitting loop: skip a run of ASCII whitespace and candidate-separating commas. Empty items,
59	                //    consecutive commas, and trailing separators are consumed here and never raise an error.
60	                while (pos < len && isWsOrComma(rawValue.charAt(pos))) pos++;
61	                if (pos >= len) break;
62	
63	                // 2. Collect the URL. An address may be quoted ('...' or "..."): the quotes only delimit the
64	                //    address and are not part of it, so commas, whitespace, and decoded entities inside them
65	                //    cannot be mistaken for candidate boundaries. An unquoted URL is a run of non-whitespace
66	                //    characters.
67	                String url;
68	                List<String> descriptors;
69	                char first = rawValue.charAt(pos);
70	                if (first == '"' || first == '\'') {
71	                    int close = rawValue.indexOf(first, pos + 1);
72	                    if (close == -1) { // unterminated quote: the rest of the value is the address, no descriptors
73	                        url = rawValue.substring(pos + 1);
74	                        pos = len;
75	                        descriptors = Collections.emptyList();
76	                    } else {
77	                        url = rawValue.substring(pos + 1, close);
78	                        pos = close + 1;
79	                        // 3. Tokenize the descriptors (see below)
80	                        TokenizerResult tokenized = tokenizeDescriptors(rawValue, pos);
81	                        descriptors = tokenized.tokens;
82	                        pos = tokenized.nextPos;
83	                    }
84	                } else {
85	                    int urlStart = pos;
86	                    while (pos < len && !StringUtil.isWhitespace(rawValue.charAt(pos))) pos++;
87	                    int urlRunEnd = pos;
88	                    int urlEnd = urlRunEnd;
89	                    while (urlEnd > urlStart && rawValue.charAt(urlEnd - 1) == ',') urlEnd--;
90	                    url = rawValue.substring(urlStart, urlEnd);
91	
92	                    if (urlEnd < urlRunEnd) {
93	                        // The URL run ended in comma(s) with no whitespace: the boundary has no descriptor and
94	                        // parsing restarts at the splitting loop. This is what keeps a comma inside a data: URL
95	                        // (e.g. "data:,Hello") part of the URL.
96	                        descriptors = Collections.emptyList();
97	                        pos = urlRunEnd;
98	                    } else {
99	                        // 3. Tokenize the descriptors with the HTML srcset state machine, so that a comma nested
100	                        //    in a parenthesized descriptor does not get mistaken for a candidate boundary.
101	                        TokenizerResult tokenized = tokenizeDescriptors(rawValue, pos);
102	                        descriptors = tokenized.tokens;
103	                        pos = tokenized.nextPos;
104	                    }
105	                }
106	
107	                if (url.isEmpty()) continue;
108	
109	                String descriptor = parseDescriptors(descriptors);
110	                String safeUrl = (descriptor != null) ? isSafeUrl(el, url, safelist) : null;
111	                if (safeUrl != null && isSerializable(safeUrl))
112	                    accepted.add(new Candidate(safeUrl, descriptor));
113	                else
114	                    dropped++;
115	            }
116	        }
117	
118	        if (accepted.isEmpty()) return new Result(null, dropped, true);
119	        return new Result(serialize(accepted), dropped, false);
120	    }
121	
122	    /** The outcome of cleaning a srcset attribute: the rewritten {@code value} (or null) and statistics. */
123	    static final class Result {
124	        final String value;
125	        final int droppedCandidates;
126	        final boolean removed;
127	
128	        private Result(String value, int droppedCandidates, boolean removed) {
129	            this.value = value;
130	            this.droppedCandidates = droppedCandidates;
131	            this.removed = removed;
132	        }
133	    }
134	
135	    private static final class TokenizerResult {
136	        final List<String> tokens;
137	        final int nextPos; // position just past the candidate-separating comma, or at end of input
138	
139	        private TokenizerResult(List<String> tokens, int nextPos) {
140	            this.tokens = tokens;
141	            this.nextPos = nextPos;
142	        }
143	    }
144	
145	    private static boolean isWsOrComma(char c) {
146	        return c == ',' || StringUtil.isWhitespace(c);
147	    }
148	
149	    /**
150	     Run the HTML srcset descriptor tokenizer starting at the first character after the URL's whitespace run.
151	     Parenthesized content (and anything quoted within it) is taken verbatim, so commas and whitespace inside it
152	     cannot start a new candidate. Stops at a boundary comma (consumed) or end of input.
153	     */
154	    private static TokenizerResult tokenizeDescriptors(String input, int pos) {
155	        List<String> tokens = new ArrayList<>();
156	        int len = input.length();
157	        int state = InDescriptor;
158	        StringBuilder token = new StringBuilder();
159	
160	        while (pos < len) {
161	            char c = input.charAt(pos);
162	            switch (state) {
163	                case InDescriptor:
164	                    if (StringUtil.isWhitespace(c)) {
165	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
166	                        state = AfterDescriptor;
167	                    } else if (c == ',') {
168	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
169	                        return new TokenizerResult(tokens, pos + 1); // consume the candidate separator
170	                    } else if (c == '(') {
171	                        token.append(c);
172	                        state = InParens;
173	                    } else {
174	                        token.append(c);
175	                    }
176	                    pos++;
177	                    break;
178	                case InParens:
179	                    token.append(c); // commas, whitespace, and quotes in here are all literal
180	                    if (c == ')') state = InDescriptor;
181	                    pos++;
182	                    break;
183	                case AfterDescriptor:
184	                    if (StringUtil.isWhitespace(c)) {
185	                        pos++;
186	                    } else if (c == ',') {
187	                        return new TokenizerResult(tokens, pos + 1);
188	                    } else {
189	                        state = InDescriptor; // reprocess this character as a new token
190	                    }
191	                    break;
192	            }
193	        }
194	        if (token.length() > 0) tokens.add(token.toString());
195	        return new TokenizerResult(tokens, pos);
196	    }
197	
198	    /**
199	     Validate the tokenized descriptor list of one candidate. Legal forms are: no descriptor, a single non-zero
200	     width ({@code <integer>w}), or a single finite positive pixel density ({@code <number>x}). Duplicated,
201	     unknown, parenthesized, or syntactically invalid descriptors invalidate the candidate.
202	     @return the normalized descriptor suffix ({@code ""} when absent, or {@code " <descriptor>"}), or {@code null}
203	     */
204	    private static String parseDescriptors(List<String> tokens) {
205	        if (tokens.isEmpty()) return "";
206	        if (tokens.size() > 1) return null;
207	
208	        String descriptor = tokens.get(0);
209	        if (descriptor.isEmpty()) return "";
210	        char suffix = descriptor.charAt(descriptor.length() - 1);
211	        if (suffix != 'w' && suffix != 'x') return null; // only lower-case width/density descriptors are valid
212	        String number = descriptor.substring(0, descriptor.length() - 1);
213	        if (number.isEmpty()) return null;
214	
215	        if (suffix == 'w') {
216	            if (parseWidth(number) == null) return null;
217	        } else {
218	            if (parseDensity(number) == null) return null;
219	        }
220	        return " " + descriptor;
221	    }
222	
223	    /** Parse a non-negative integer with no sign, exponent, or decimal point; zero and overflow are invalid. */
224	    private static Long parseWidth(String s) {
225	        long value = 0;
226	        for (int i = 0; i < s.length(); i++) {
227	            char c = s.charAt(i);
228	            if (c < '0' || c > '9') return null;
229	            int digit = c - '0';
230	            if (value > (Long.MAX_VALUE - digit) / 10) return null; // overflow
231	            value = value * 10 + digit;
232	        }
233	        return value == 0L ? null : value;
234	    }
235	
236	    /** Parse a finite positive floating-point number matching the HTML valid floating-point number grammar. */
237	    private static Double parseDensity(String s) {
238	        int i = 0;
239	        if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
240	            if (s.charAt(i) == '-') return null;
241	            i++;
242	        }
243	        int intDigits = 0;
244	        while (i < s.length() && isAsciiDigit(s.charAt(i))) { intDigits++; i++; }
245	        int fracDigits = 0;
246	        if (i < s.length() && s.charAt(i) == '.') {
247	            i++;
248	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { fracDigits++; i++; }
249	        }
250	        // grammar: digits before the optional dot, or digits after it (".5"); a lone "." is invalid
251	        if (intDigits == 0 && fracDigits == 0) return null;
252	        if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
253	            i++;
254	            if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) i++;
255	            int exponentDigits = 0;
256	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { exponentDigits++; i++; }
257	            if (exponentDigits == 0) return null;
258	        }
259	        if (i != s.length()) return null; // trailing junk
260	        try {
261	            double value = Double.parseDouble(s);
262	            // only positive densities are meaningful; zero, negative, and non-finite values invalidate the candidate
263	            if (value <= 0d || Double.isNaN(value) || Double.isInfinite(value)) return null;
264	            return value;
265	        } catch (NumberFormatException e) {
266	            return null;
267	        }
268	    }
269	
270	    private static boolean isAsciiDigit(char c) {
271	        return c >= '0' && c <= '9';
272	    }
273	
274	    /**
275	     Check one candidate URL against the safelist's protocol policy and return the URL spelling to emit.
276	     <p>
277	     This mirrors the ordinary URI attribute path in {@link Safelist}: the URL is resolved against the element's base
278	     URI (which strips and percent-normalizes control characters the same way {@code src} does), and the resolved or
279	     as-written value must begin with an allowed scheme. When relative links are not preserved, resolvable candidates
280	     are emitted in absolute form, exactly like an ordinary {@code src} value.
281	     </p>
282	     @return the URL to keep (absolute or original spelling), or {@code null} if it must be dropped
283	     */
284	    private static String isSafeUrl(Element el, String url, Safelist safelist) {
285	        Set<Safelist.Protocol> protocols = safelist.srcsetProtocols(el.normalName());
286	        if (protocols.isEmpty()) return stripControlChars(url); // no protocol policy: accept, like an ordinary untyped attribute
287	
288	        String resolved = StringUtil.resolve(el.baseUri(), url);
289	        String check = resolved;
290	        if (check.isEmpty() && !StringUtil.hasHttpScheme(url)) check = url; // custom schemes checked as written
291	        check = stripControlChars(check);
292	        if (check.isEmpty()) return null; // an unresolvable relative URL with no base is not acceptable
293	
294	        String lc = Normalizer.lowerCase(check);
295	        for (Safelist.Protocol protocol : protocols) {
296	            String prot = protocol.toString();
297	            if (prot.equals("#")) continue; // fragment anchors are not image candidates
298	            if (lc.startsWith(prot)
299	                && lc.length() > prot.length()
300	                && lc.charAt(prot.length()) == ':') {
301	                // Emit the absolute form like an ordinary src value, unless relative links are preserved; in either
302	                // case strip ASCII control characters, which browsers remove from URLs and would destabilize reparse.
303	                String emit = (!safelist.preserveRelativeLinks() && !resolved.isEmpty()) ? resolved : url;
304	                return stripControlChars(emit);
305	            }
306	        }
307	        return null;
308	    }
309	
310	    private static String stripControlChars(String url) {
311	        StringBuilder sb = null;
312	        for (int i = 0; i < url.length(); i++) {
313	            char c = url.charAt(i);
314	            if (c <= 0x1f) {
315	                if (sb == null) {
316	                    sb = new StringBuilder(url.length());
317	                    sb.append(url, 0, i);
318	                }
319	            } else if (sb != null) {
320	                sb.append(c);
321	            }
322	        }
323	        return sb == null ? url : sb.toString();
324	    }
325	
326	    private static String serialize(List<Candidate> candidates) {
327	        StringBuilder sb = StringUtil.borrowBuilder();
328	        for (int i = 0; i < candidates.size(); i++) {
329	            if (i > 0) sb.append(", ");
330	            Candidate candidate = candidates.get(i);
331	            appendUrl(sb, candidate.url);
332	            sb.append(candidate.descriptor);
333	        }
334	        return StringUtil.releaseBuilder(sb);
335	    }
336	
337	    /**
338	     Append one URL, re-quoting it when its bare spelling would not reparse into the same candidate: that is the
339	     case when it contains whitespace, ends in a comma (which the parser would strip as a separator), or starts
340	     with a quote character. {@link #isSerializable} guarantees a usable quote character is available.
341	     */
342	    private static void appendUrl(StringBuilder sb, String url) {
343	        if (!needsQuotes(url)) {
344	            sb.append(url);
345	            return;
346	        }
347	        char quote = url.indexOf('"') == -1 ? '"' : '\'';
348	        sb.append(quote).append(url).append(quote);
349	    }
350	
351	    private static boolean needsQuotes(String url) {
352	        if (url.isEmpty()) return false;
353	        char first = url.charAt(0);
354	        if (first == '"' || first == '\'' || url.charAt(url.length() - 1) == ',') return true;
355	        for (int i = 0; i < url.length(); i++)
356	            if (StringUtil.isWhitespace(url.charAt(i))) return true;
357	        return false;
358	    }
359	
360	    /** A URL that needs quotes but contains both quote characters cannot be serialized reparseably. */
361	    private static boolean isSerializable(String url) {
362	        return !needsQuotes(url) || url.indexOf('"') == -1 || url.indexOf('\'') == -1;
363	    }
364	
365	    private static final class Candidate {
366	        final String url;
367	        final String descriptor; // normalized as "" or " <descriptor>"
368	
369	        Candidate(String url, String descriptor) {
370	            this.url = url;
371	            this.descriptor = descriptor;
372	        }
373	    }
374	}
