import org.jsoup.Jsoup;
import org.jsoup.safety.*;
import org.jsoup.nodes.Document;
public class Probe4 {
    static Safelist sl() { return Safelist.relaxed().addAttributes("img", "srcset"); }
    static void p(String label, String html) {
        String c1 = Jsoup.clean(html, "http://example.com/", sl());
        String c2 = Jsoup.clean(c1, "http://example.com/", sl());
        String c3 = Jsoup.clean(Jsoup.parse(c1).body().html(), "http://example.com/", sl());
        System.out.println(label + ": " + c1 + (c1.equals(c2)&&c1.equals(c3)?"":"  <<< UNSTABLE"));
    }
    public static void main(String[] x) {
        p("double quote inner comma", "<img srcset='\"http://example.com/a,b.jpg\" 1x, http://example.com/c.jpg 2x'>");
        p("single quote inner space", "<img srcset=\"'http://example.com/a b.jpg' 1x, http://example.com/c.jpg 2x\">");
        p("quoted no descriptor", "<img srcset='\"http://example.com/a,b.jpg\", http://example.com/c.jpg 2x'>");
        p("quoted javascript", "<img srcset='\"javascript:alert(1)\", http://example.com/c.jpg 2x'>");
        p("two quoted, second has space", "<img srcset='\"http://example.com/a,b.jpg\" 1x, \"http://example.com/c d.jpg\" 2x'>");
        p("quoted relative inner comma", "<img srcset='\"/a,b.jpg\" 1x, /c.jpg 2x'>");
        p("quoted relative space preserveRelative", null);
        Safelist pr = sl().preserveRelativeLinks(true);
        String c = Jsoup.clean("<img srcset='\"/a b.jpg\" 1x, /c.jpg 2x'>", "http://example.com/", pr);
        String c2 = Jsoup.clean(c, "http://example.com/", pr);
        System.out.println("preserveRelative space: " + c + (c.equals(c2)?"":" <<< UNSTABLE"));
        // width strictness new cases
        String[] w = {"0w","+1w","-1w","1.5w","100W","1w 2w","2w 1x","٣w","1ｗ"};
        for (String d : w) {
            String html = "<img srcset=\"http://example.com/a.jpg " + d + ", http://example.com/b.jpg 2x\">";
            p("width "+d, html);
        }
    }
}
