import org.jsoup.Jsoup;
import org.jsoup.safety.*;
import org.jsoup.nodes.Document;
import java.util.*;

public class Fuzz {
    static final Safelist SL = Safelist.relaxed().addAttributes("img", "srcset");
    static final Safelist PR = Safelist.relaxed().addAttributes("img","srcset").preserveRelativeLinks(true);
    static final Safelist NP = new Safelist().addTags("img").addAttributes("img","srcset");
    static final String BASE = "http://example.com/path/";
    static final Random R = new Random(42);

    static String attr() {
        String[] urls = {
            "http://example.com/a.jpg","/a.jpg","a.jpg","data:,x","javascript:alert(1)",
            "http://example.com/a,b.jpg","http://example.com/a b.jpg","http://example.com/a(b).jpg",
            "http://example.com/q?x=1&amp;y=2","http://example.com/c&#x09;.jpg","#frag",
            "http://example.com/a.jpg","http://example.com/b.jpg"
        };
        String[] desc = {"","1x","2x","0x","-1x","0.5x","1e999x","1w","0w","300w","+3w","1.5w","100W",
                         "1w 2w","2w 1x","(min-width: 1px, x: y)","nope","w","  ","\t1x"};
        StringBuilder sb = new StringBuilder();
        int n = 1 + R.nextInt(4);
        for (int i=0;i<n;i++){
            if (R.nextInt(6)==0){ sb.append(","); continue; }
            String u = urls[R.nextInt(urls.length)];
            // entity-decode some urls on purpose by injecting raw markup? parser handles
            if (R.nextBoolean()) {
                char q = R.nextBoolean()?'"':'\'';
                u = q+u+q;
            }
            sb.append(u);
            String d = desc[R.nextInt(desc.length)];
            if (!d.isEmpty()) {
                sb.append(R.nextBoolean()?" ":"\t");
                sb.append(d);
            }
            if (i<n-1) sb.append(R.nextBoolean()?", ":",\n");
        }
        return sb.toString();
    }

    static String clean(String value, Safelist sl) {
        Document d = Jsoup.parseBodyFragment("<img srcset=\"" + value.replace("\"","&quot;") + "\">", BASE);
        return new Cleaner(sl).clean(d).body().html();
    }

    public static void main(String[] a) {
        Safelist[] lists = {SL, PR, NP};
        int violations = 0;
        for (int iter=0; iter<200000; iter++) {
            Safelist sl = lists[R.nextInt(lists.length)];
            String v = attr();
            String once, twice, reparsed;
            try {
                once = clean(v, sl);
                twice = clean(Jsoup.parse(once).body().html().replaceAll("^<img[^>]*srcset=\"","").replaceAll("\">?$",""), sl);
                // simpler: clean the serialized html directly
                Document d1 = new Cleaner(sl).clean(Jsoup.parseBodyFragment(
                    Jsoup.parse(once).body().html(), BASE));
                reparsed = d1.body().html();
            } catch (Exception e) {
                System.out.println("THREW on: " + v + " -> " + e); violations++; continue;
            }
            if (!once.equals(reparsed)) {
                System.out.println("NON-IDEMPOTENT\n in : " + v + "\n one: " + once + "\n rep: " + reparsed);
                if (++violations > 20) break;
            }
            // no javascript/data leaks under relaxed (only http/https)
            String low = once.toLowerCase();
            if (sl == SL && (low.contains("javascript") || low.contains("srcset=\"data:"))) {
                System.out.println("LEAK: " + once); if (++violations>20) break;
            }
            // delimiting quote chars must not remain in an attribute that survived
            if (once.contains("srcset=") && (once.contains("&quot;") || once.contains("'http"))) {
                System.out.println("QUOTE LEAK: " + once + "   <- " + v); if (++violations>20) break;
            }
            // an empty srcset attribute must never remain
            if (once.contains("srcset=\"\"")) { System.out.println("EMPTY: "+once); if(++violations>20)break; }
        }
        System.out.println(violations==0 ? "ALL 200000 FUZZ CASES STABLE" : ("violations="+violations));
    }
}
